contracts/game/Bank.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

interface IGameController {
    function isAccountFrozen(address) external view returns (bool);
}

interface IPriceOracle {
    function getPrice(string calldata symbol) external view returns (uint256);
}

/**
 * @title Bank
 * @dev Lending/borrowing for Chain City. Deposits, loans, liquidation with 10% bonus.
 */
contract Bank {
    IGameController public gameController;
    IPriceOracle public priceOracle;
    address public admin;

    uint256 public interestRate = 200; // basis points, e.g. 200 = 2%
    uint256 public collateralRatio = 15000; // 150% = 15000 bps

    struct Deposit {
        uint256 amount;
        uint256 lastAccrualBlock;
    }

    struct Loan {
        address borrower;
        uint256 principal;
        uint256 collateral; // in wei (ETH)
        uint256 accruedInterest;
        uint256 lastAccrualBlock;
        bool active;
    }

    mapping(address => Deposit) public deposits;
    mapping(address => Loan) public loans;
    uint256 public totalDeposits;
    uint256 public totalLoans;

    event Deposited(address indexed account, uint256 amount);
    event Withdrawn(address indexed account, uint256 amount);
    event Borrowed(address indexed borrower, uint256 principal, uint256 collateral);
    event Repaid(address indexed borrower, uint256 amount);
    event Liquidated(address indexed borrower, address indexed liquidator, uint256 collateralSeized);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Bank: not admin");
        _;
    }

    constructor(address _gameController, address _priceOracle) {
        admin = msg.sender;
        gameController = IGameController(_gameController);
        priceOracle = IPriceOracle(_priceOracle);
    }

    function setInterestRate(uint256 _rate) external onlyAdmin {
        interestRate = _rate;
    }

    function setCollateralRatio(uint256 _ratio) external onlyAdmin {
        collateralRatio = _ratio;
    }

    function deposit() external payable {
        require(!gameController.isAccountFrozen(msg.sender), "Bank: account frozen");
        require(msg.value > 0, "Bank: zero amount");

        if (deposits[msg.sender].amount > 0) {
            _accrueDepositInterest(msg.sender);
        } else {
            deposits[msg.sender].lastAccrualBlock = block.number;
        }
        deposits[msg.sender].amount += msg.value;
        totalDeposits += msg.value;
        emit Deposited(msg.sender, msg.value);
    }

    function withdraw(uint256 amount) external {
        require(!gameController.isAccountFrozen(msg.sender), "Bank: account frozen");
        require(amount > 0, "Bank: zero amount");
        _accrueDepositInterest(msg.sender);
        require(deposits[msg.sender].amount >= amount, "Bank: insufficient deposit");

        deposits[msg.sender].amount -= amount;
        totalDeposits -= amount;
        (bool ok,) = payable(msg.sender).call{value: amount}("");
        require(ok, "Bank: transfer failed");
        emit Withdrawn(msg.sender, amount);
    }

    function borrow(uint256 principal) external payable {
        require(!gameController.isAccountFrozen(msg.sender), "Bank: account frozen");
        require(principal > 0 && msg.value > 0, "Bank: invalid amounts");
        require(loans[msg.sender].active == false, "Bank: existing loan");

        uint256 minCollateral = (principal * collateralRatio) / 10000;
        require(msg.value >= minCollateral, "Bank: insufficient collateral");

        require(address(this).balance >= principal, "Bank: insufficient liquidity");

        loans[msg.sender] = Loan({
            borrower: msg.sender,
            principal: principal,
            collateral: msg.value,
            accruedInterest: 0,
            lastAccrualBlock: block.number,
            active: true
        });
        totalLoans += principal;

        (bool ok,) = payable(msg.sender).call{value: principal}("");
        require(ok, "Bank: transfer failed");
        emit Borrowed(msg.sender, principal, msg.value);
    }

    function repay() external payable {
        require(loans[msg.sender].active, "Bank: no active loan");
        require(msg.value > 0, "Bank: zero payment");

        _accrueLoanInterest(msg.sender);
        Loan storage loan = loans[msg.sender];
        uint256 totalOwed = loan.principal + loan.accruedInterest;
        uint256 repayAmount = msg.value > totalOwed ? totalOwed : msg.value;

        uint256 toPrincipal = 0;
        if (repayAmount <= loan.accruedInterest) {
            loan.accruedInterest -= repayAmount;
        } else {
            toPrincipal = repayAmount - loan.accruedInterest;
            loan.accruedInterest = 0;
            loan.principal -= toPrincipal;
        }

        totalLoans -= toPrincipal;

        if (loan.principal == 0) {
            uint256 refundCollateral = loan.collateral;
            loan.collateral = 0;
            loan.active = false;
            (bool ok,) = payable(msg.sender).call{value: refundCollateral}("");
            require(ok, "Bank: collateral refund failed");
        }

        if (msg.value > repayAmount) {
            (bool refund,) = payable(msg.sender).call{value: msg.value - repayAmount}("");
            require(refund, "Bank: refund failed");
        }
        emit Repaid(msg.sender, repayAmount);
    }

    function liquidate(address borrower) external {
        require(!gameController.isAccountFrozen(msg.sender), "Bank: account frozen");
        Loan storage loan = loans[borrower];
        require(loan.active, "Bank: no active loan");

        _accrueLoanInterest(borrower);
        uint256 totalOwed = loan.principal + loan.accruedInterest;
        require(
            loan.collateral * 10000 < totalOwed * collateralRatio,
            "Bank: not undercollateralized"
        );

        uint256 collateralToSeize = loan.collateral;
        uint256 bonus = (collateralToSeize * 1000) / 10000; // 10% to liquidator
        uint256 toLiquidator = bonus;

        loan.active = false;
        loan.principal = 0;
        loan.accruedInterest = 0;
        loan.collateral = 0;
        totalLoans -= totalOwed;

        (bool ok1,) = payable(msg.sender).call{value: toLiquidator}("");
        require(ok1, "Bank: liquidator transfer failed");
        emit Liquidated(borrower, msg.sender, collateralToSeize);
    }

    function accrueInterest() external onlyAdmin {
        for (uint256 i = 0; i < 100; i++) {
            // Simplified - in production we'd iterate over active loans
            break;
        }
    }

    function getDepositInfo(address account)
        external
        view
        returns (uint256 amount, uint256 lastAccrualBlock)
    {
        return (deposits[account].amount, deposits[account].lastAccrualBlock);
    }

    function getLoanInfo(address account)
        external
        view
        returns (
            uint256 principal,
            uint256 collateral,
            uint256 accruedInterest,
            bool active
        )
    {
        Loan storage loan = loans[account];
        return (loan.principal, loan.collateral, loan.accruedInterest, loan.active);
    }

    function getBankStats()
        external
        view
        returns (uint256 deposits_, uint256 loans_, uint256 liquidity)
    {
        return (totalDeposits, totalLoans, address(this).balance);
    }

    function _accrueDepositInterest(address account) internal {
        // Simplified - no interest on deposits for this game
    }

    function _accrueLoanInterest(address account) internal {
        Loan storage loan = loans[account];
        if (!loan.active) return;
        uint256 blocks = block.number - loan.lastAccrualBlock;
        loan.accruedInterest += (loan.principal * interestRate * blocks) / (10000 * 1000);
        loan.lastAccrualBlock = block.number;
    }

    receive() external payable {}
}

contracts/game/CarLot.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {ERC721URIStorage} from "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";

interface IGameController {
    function isAccountFrozen(address) external view returns (bool);
}

interface IInspectionRegistry {
    function verifyInspection(bytes32 hash) external view returns (bool isValid, uint256);
}

/**
 * @title CarLot
 * @dev Car NFT marketplace for Chain City. ERC721 cars with inspection verification.
 */
contract CarLot is ERC721, ERC721URIStorage {
    IGameController public gameController;
    IInspectionRegistry public inspectionRegistry;
    address public admin;

    struct CarListing {
        uint256 tokenId;
        address seller;
        uint256 price;
        bool active;
    }

    struct CarRecord {
        bytes32 inspectionHash;
        uint256 mileage;
        uint256 mintEpoch;
    }

    mapping(uint256 => CarListing) public listings;
    mapping(uint256 => CarRecord) public carRecords;
    mapping(uint256 => uint256[]) public priceHistory;
    mapping(uint256 => address[]) public ownerHistory;

    uint256 private _nextTokenId;

    event CarMinted(uint256 indexed tokenId, address to, bytes32 inspectionHash, uint256 mileage);
    event CarListed(uint256 indexed tokenId, address seller, uint256 price);
    event CarSold(uint256 indexed tokenId, address buyer, uint256 price);
    event CarDelisted(uint256 indexed tokenId);

    modifier onlyAdmin() {
        require(msg.sender == admin, "CarLot: not admin");
        _;
    }

    constructor(address _gameController, address _inspectionRegistry)
        ERC721("Chain City Car", "CCCAR")
    {
        admin = msg.sender;
        gameController = IGameController(_gameController);
        inspectionRegistry = IInspectionRegistry(_inspectionRegistry);
    }

    function mintCar(address to, bytes32 inspectionHash, uint256 mileage, string calldata tokenURI_)
        external
        onlyAdmin
    {
        _mintCar(to, inspectionHash, mileage, tokenURI_);
    }

    function _mintCar(address to, bytes32 inspectionHash, uint256 mileage, string memory tokenURI_)
        internal
    {
        uint256 tokenId = _nextTokenId++;
        _safeMint(to, tokenId);
        _setTokenURI(tokenId, tokenURI_);
        carRecords[tokenId] = CarRecord({
            inspectionHash: inspectionHash,
            mileage: mileage,
            mintEpoch: 0
        });
        ownerHistory[tokenId].push(to);
        emit CarMinted(tokenId, to, inspectionHash, mileage);
    }

    function mintBatchCars(
        address[] calldata recipients,
        bytes32[] calldata inspectionHashes,
        uint256[] calldata mileages,
        string[] calldata tokenURIs
    ) external onlyAdmin {
        require(
            recipients.length == inspectionHashes.length
                && recipients.length == mileages.length
                && recipients.length == tokenURIs.length,
            "CarLot: length mismatch"
        );
        for (uint256 i = 0; i < recipients.length; i++) {
            _mintCar(recipients[i], inspectionHashes[i], mileages[i], tokenURIs[i]);
        }
    }

    function listCar(uint256 tokenId, uint256 price) external {
        require(ownerOf(tokenId) == msg.sender, "CarLot: not owner");
        require(!gameController.isAccountFrozen(msg.sender), "CarLot: account frozen");
        require(!listings[tokenId].active, "CarLot: already listed");

        listings[tokenId] = CarListing({tokenId: tokenId, seller: msg.sender, price: price, active: true});
        priceHistory[tokenId].push(price);
        emit CarListed(tokenId, msg.sender, price);
    }

    function buyCar(uint256 tokenId) external payable {
        CarListing storage listing = listings[tokenId];
        require(listing.active, "CarLot: not listed");
        require(msg.value >= listing.price, "CarLot: insufficient payment");
        require(!gameController.isAccountFrozen(msg.sender), "CarLot: account frozen");
        require(!gameController.isAccountFrozen(listing.seller), "CarLot: seller frozen");

        address seller = listing.seller;
        listing.active = false;

        _transfer(seller, msg.sender, tokenId);
        (bool ok,) = payable(seller).call{value: listing.price}("");
        require(ok, "CarLot: transfer failed");

        if (msg.value > listing.price) {
            (bool refund,) = payable(msg.sender).call{value: msg.value - listing.price}("");
            require(refund, "CarLot: refund failed");
        }

        priceHistory[tokenId].push(listing.price);
        ownerHistory[tokenId].push(msg.sender);
        emit CarSold(tokenId, msg.sender, listing.price);
    }

    function delistCar(uint256 tokenId) external {
        require(ownerOf(tokenId) == msg.sender, "CarLot: not owner");
        require(listings[tokenId].active, "CarLot: not listed");
        listings[tokenId].active = false;
        emit CarDelisted(tokenId);
    }

    function getCarHistory(uint256 tokenId)
        external
        view
        returns (uint256[] memory prices, address[] memory owners)
    {
        return (priceHistory[tokenId], ownerHistory[tokenId]);
    }

    function getTokenMetadata(uint256 tokenId)
        external
        view
        returns (bytes32 inspectionHash, uint256 mileage, string memory uri)
    {
        CarRecord storage r = carRecords[tokenId];
        return (r.inspectionHash, r.mileage, tokenURI(tokenId));
    }

    function getActiveListings() external view returns (uint256[] memory tokenIds) {
        uint256 count = 0;
        for (uint256 i = 0; i < _nextTokenId; i++) {
            if (listings[i].active) count++;
        }
        tokenIds = new uint256[](count);
        uint256 j = 0;
        for (uint256 i = 0; i < _nextTokenId; i++) {
            if (listings[i].active) {
                tokenIds[j++] = i;
            }
        }
    }

    function getInspectionStatus(uint256 tokenId) external view returns (bool isValid, uint256 epoch) {
        return inspectionRegistry.verifyInspection(carRecords[tokenId].inspectionHash);
    }

    function supportsInterface(bytes4 interfaceId) public view override(ERC721, ERC721URIStorage) returns (bool) {
        return super.supportsInterface(interfaceId);
    }

    function _burn(uint256 tokenId) internal override(ERC721, ERC721URIStorage) {
        super._burn(tokenId);
    }

    function tokenURI(uint256 tokenId) public view override(ERC721, ERC721URIStorage) returns (string memory) {
        return super.tokenURI(tokenId);
    }
}

contracts/game/GameController.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./TimelockEscrow.sol";

/**
 * @title GameController
 * @dev Master contract for Chain City game. Admin = deployer.
 */
contract GameController {
    address public admin;

    uint256 public currentEpoch;
    bool public gameActive;
    uint256 public maxEpochs;
    uint256 public startingBalance;
    uint256 public playerCap;

    struct Player {
        address addr;
        string secretObjective;
        bool registered;
    }

    mapping(address => Player) public players;
    address[] public playerAddresses;
    mapping(address => bool) public isRegistered;

    mapping(uint256 => mapping(address => uint256)) public balanceSnapshots;
    mapping(uint256 => uint256) public epochTimestamps;

    mapping(address => bool) public frozenAccounts;

    address public carLot;

    event GameStarted(uint256 maxEpochs, uint256 startingBalance);
    event PlayerRegistered(address indexed player);
    event PlayerRemoved(address indexed player);
    event EpochAdvanced(uint256 newEpoch);
    event ObjectiveAssigned(address indexed player, string objective);
    event AccountFrozen(address indexed account);
    event AccountUnfrozen(address indexed account);
    event PlayerSlashed(address indexed player, uint256 amount);
    event PlayerRewarded(address indexed player, uint256 amount);

    modifier onlyAdmin() {
        require(msg.sender == admin, "GameController: not admin");
        _;
    }

    modifier onlyRegistered(address addr) {
        require(isRegistered[addr], "GameController: not registered");
        _;
    }

    constructor() payable {
        admin = msg.sender;
        currentEpoch = 0;
        gameActive = false;
        maxEpochs = 10;
        startingBalance = 100 ether;
        playerCap = 50;
        require(address(this).balance >= 1000 ether, "GameController: need 1000 ETH");
    }

    function setCarLot(address _carLot) external onlyAdmin {
        carLot = _carLot;
    }

    function startGame(uint256 _maxEpochs, uint256 _startingBalance) external onlyAdmin {
        require(!gameActive, "GameController: game already active");
        maxEpochs = _maxEpochs;
        startingBalance = _startingBalance;
        gameActive = true;
        currentEpoch = 1;
        epochTimestamps[1] = block.timestamp;

        for (uint256 i = 0; i < playerAddresses.length; i++) {
            address p = playerAddresses[i];
            if (players[p].registered) {
                (bool ok,) = payable(p).call{value: startingBalance}("");
                require(ok, "GameController: start transfer failed");
            }
        }
        emit GameStarted(maxEpochs, startingBalance);
    }

    function registerPlayer(address player) external onlyAdmin {
        require(!isRegistered[player], "GameController: already registered");
        require(playerAddresses.length < playerCap, "GameController: player cap reached");
        players[player] = Player({addr: player, secretObjective: "", registered: true});
        playerAddresses.push(player);
        isRegistered[player] = true;
        emit PlayerRegistered(player);
    }

    function removePlayer(address player) external onlyAdmin {
        require(isRegistered[player], "GameController: not registered");
        players[player].registered = false;
        isRegistered[player] = false;
        emit PlayerRemoved(player);
    }

    function advanceEpoch() external onlyAdmin {
        require(gameActive, "GameController: game not active");
        require(currentEpoch < maxEpochs, "GameController: max epochs reached");

        for (uint256 i = 0; i < playerAddresses.length; i++) {
            address p = playerAddresses[i];
            if (players[p].registered) {
                balanceSnapshots[currentEpoch][p] = p.balance;
            }
        }

        currentEpoch++;
        epochTimestamps[currentEpoch] = block.timestamp;

        if (currentEpoch >= maxEpochs) {
            gameActive = false;
        }
        emit EpochAdvanced(currentEpoch);
    }

    function assignSecretObjective(address player, string calldata objective) external onlyAdmin {
        require(isRegistered[player], "GameController: not registered");
        players[player].secretObjective = objective;
        emit ObjectiveAssigned(player, objective);
    }

    function injectEvent_AccountFreeze(address account) external onlyAdmin {
        frozenAccounts[account] = true;
        emit AccountFrozen(account);
    }

    function unfreezeAccount(address account) external onlyAdmin {
        frozenAccounts[account] = false;
        emit AccountUnfrozen(account);
    }

    function slashPlayer(address player, uint256 amount) external onlyAdmin {
        require(isRegistered[player], "GameController: not registered");
        require(address(this).balance >= amount, "GameController: insufficient balance");
        (bool ok,) = payable(admin).call{value: amount}("");
        require(ok, "GameController: slash transfer failed");
        emit PlayerSlashed(player, amount);
    }

    function rewardPlayer(address player, uint256 amount) external onlyAdmin {
        require(isRegistered[player], "GameController: not registered");
        require(address(this).balance >= amount, "GameController: insufficient balance");
        (bool ok,) = payable(player).call{value: amount}("");
        require(ok, "GameController: reward transfer failed");
        emit PlayerRewarded(player, amount);
    }

    function injectEvent_Ransomware(
        address victim,
        address paymentAddress,
        uint256 amount,
        uint256 deadlineEpoch
    ) external onlyAdmin returns (address) {
        TimelockEscrow escrow = new TimelockEscrow(
            victim,
            paymentAddress,
            amount,
            deadlineEpoch,
            address(this)
        );
        return address(escrow);
    }

    function injectEvent_Airdrop(address[] calldata recipients, uint256 amountEach) external onlyAdmin {
        for (uint256 i = 0; i < recipients.length; i++) {
            (bool ok,) = payable(recipients[i]).call{value: amountEach}("");
            require(ok, "GameController: airdrop failed");
        }
    }

    function injectEvent_MarketShock(int256 priceDeltaPercent) external onlyAdmin {
        // Market shock - downstream contracts (Bank, CarLot via PriceOracle) handle this
        // GameController just emits/logs; actual price updates are in PriceOracle
        // This is a no-op here - the deploy script or indexer can react
    }

    function getLeaderboard() external view returns (address[] memory, uint256[] memory) {
        address[] memory addrs = new address[](playerAddresses.length);
        uint256[] memory balances = new uint256[](playerAddresses.length);
        for (uint256 i = 0; i < playerAddresses.length; i++) {
            addrs[i] = playerAddresses[i];
            balances[i] = players[playerAddresses[i]].registered ? playerAddresses[i].balance : 0;
        }
        return (addrs, balances);
    }

    function getPlayerBalance(address player) external view returns (uint256) {
        return player.balance;
    }

    function getBalanceHistory(address player, uint256 fromEpoch, uint256 toEpoch)
        external
        view
        returns (uint256[] memory)
    {
        uint256 len = toEpoch >= fromEpoch ? toEpoch - fromEpoch + 1 : 0;
        uint256[] memory hist = new uint256[](len);
        for (uint256 i = 0; i < len; i++) {
            hist[i] = balanceSnapshots[fromEpoch + i][player];
        }
        return hist;
    }

    function getPlayerCount() external view returns (uint256) {
        uint256 c = 0;
        for (uint256 i = 0; i < playerAddresses.length; i++) {
            if (players[playerAddresses[i]].registered) c++;
        }
        return c;
    }

    function isAccountFrozen(address account) external view returns (bool) {
        return frozenAccounts[account];
    }

    function getGameState()
        external
        view
        returns (uint256 epoch, bool active, uint256 maxE, uint256 playerCount)
    {
        return (currentEpoch, gameActive, maxEpochs, this.getPlayerCount());
    }

    receive() external payable {}
}

