// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title InspectionRegistry
 * @dev Registry of valid car inspection hashes for Chain City.
 */
contract InspectionRegistry {
    address public admin;

    mapping(bytes32 => bool) public validInspections;
    mapping(bytes32 => uint256) public inspectionDates;

    event InspectionRegistered(bytes32 indexed hash, uint256 epoch);

    modifier onlyAdmin() {
        require(msg.sender == admin, "InspectionRegistry: not admin");
        _;
    }

    constructor() {
        admin = msg.sender;
    }

    function registerInspection(bytes32 hash, uint256 epoch) external onlyAdmin {
        validInspections[hash] = true;
        inspectionDates[hash] = epoch;
        emit InspectionRegistered(hash, epoch);
    }

    function registerBatchInspections(bytes32[] calldata hashes, uint256[] calldata epochs)
        external
        onlyAdmin
    {
        require(hashes.length == epochs.length, "InspectionRegistry: length mismatch");
        for (uint256 i = 0; i < hashes.length; i++) {
            validInspections[hashes[i]] = true;
            inspectionDates[hashes[i]] = epochs[i];
            emit InspectionRegistered(hashes[i], epochs[i]);
        }
    }

    function verifyInspection(bytes32 hash) external view returns (bool isValid, uint256 inspectionEpoch) {
        return (validInspections[hash], inspectionDates[hash]);
    }
}

contracts/game/InsuranceDesk.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

interface IGameController {
    function isAccountFrozen(address) external view returns (bool);
}

/**
 * @title InsuranceDesk
 * @dev Insurance policies for Chain City. Purchase, file claim, approve/deny.
 */
contract InsuranceDesk {
    IGameController public gameController;
    address public admin;
    address public underwriter;

    uint256 public poolBalance;

    enum ClaimStatus {
        None,
        Pending,
        Approved,
        Denied
    }

    struct Policy {
        address holder;
        uint256 premium;
        uint256 coverage;
        uint256 startEpoch;
        bool active;
        ClaimStatus claimStatus;
        uint256 claimAmount;
    }

    mapping(uint256 => Policy) public policies;
    uint256 public policyCounter;

    event PoolFunded(uint256 amount);
    event UnderwriterSet(address indexed underwriter);
    event PolicyPurchased(uint256 indexed id, address holder, uint256 premium, uint256 coverage);
    event ClaimFiled(uint256 indexed id, uint256 amount);
    event ClaimApproved(uint256 indexed id);
    event ClaimDenied(uint256 indexed id);

    modifier onlyAdmin() {
        require(msg.sender == admin, "InsuranceDesk: not admin");
        _;
    }

    modifier onlyUnderwriter() {
        require(msg.sender == underwriter, "InsuranceDesk: not underwriter");
        _;
    }

    constructor(address _gameController) {
        admin = msg.sender;
        gameController = IGameController(_gameController);
    }

    function fundPool() external payable {
        require(msg.value > 0, "InsuranceDesk: zero amount");
        poolBalance += msg.value;
        emit PoolFunded(msg.value);
    }

    function setUnderwriter(address _underwriter) external onlyAdmin {
        underwriter = _underwriter;
        emit UnderwriterSet(_underwriter);
    }

    function purchasePolicy(uint256 coverage) external payable {
        require(!gameController.isAccountFrozen(msg.sender), "InsuranceDesk: account frozen");
        require(coverage > 0 && msg.value > 0, "InsuranceDesk: invalid amounts");

        uint256 premium = (coverage * 10) / 100; // 10% premium
        require(msg.value >= premium, "InsuranceDesk: insufficient premium");

        policies[policyCounter] = Policy({
            holder: msg.sender,
            premium: premium,
            coverage: coverage,
            startEpoch: 0,
            active: true,
            claimStatus: ClaimStatus.None,
            claimAmount: 0
        });
        emit PolicyPurchased(policyCounter, msg.sender, premium, coverage);
        policyCounter++;

        if (msg.value > premium) {
            (bool refund,) = payable(msg.sender).call{value: msg.value - premium}("");
            require(refund, "InsuranceDesk: refund failed");
        }
    }

    function fileClaim(uint256 policyId, uint256 amount) external {
        Policy storage p = policies[policyId];
        require(p.active, "InsuranceDesk: policy inactive");
        require(p.holder == msg.sender, "InsuranceDesk: not holder");
        require(p.claimStatus == ClaimStatus.None, "InsuranceDesk: claim exists");
        require(amount <= p.coverage, "InsuranceDesk: exceeds coverage");

        p.claimStatus = ClaimStatus.Pending;
        p.claimAmount = amount;
        emit ClaimFiled(policyId, amount);
    }

    function approveClaim(uint256 policyId) external onlyUnderwriter {
        Policy storage p = policies[policyId];
        require(p.claimStatus == ClaimStatus.Pending, "InsuranceDesk: not pending");
        require(poolBalance >= p.claimAmount, "InsuranceDesk: insufficient pool");

        p.claimStatus = ClaimStatus.Approved;
        p.active = false;
        poolBalance -= p.claimAmount;
        (bool ok,) = payable(p.holder).call{value: p.claimAmount}("");
        require(ok, "InsuranceDesk: transfer failed");
        emit ClaimApproved(policyId);
    }

    function denyClaim(uint256 policyId) external onlyUnderwriter {
        Policy storage p = policies[policyId];
        require(p.claimStatus == ClaimStatus.Pending, "InsuranceDesk: not pending");

        p.claimStatus = ClaimStatus.Denied;
        emit ClaimDenied(policyId);
    }

    function getPoolHealth() external view returns (uint256 balance, uint256 totalCoverage) {
        uint256 coverage = 0;
        for (uint256 i = 0; i < policyCounter; i++) {
            if (policies[i].active && policies[i].claimStatus == ClaimStatus.Pending) {
                coverage += policies[i].claimAmount;
            }
        }
        return (poolBalance, coverage);
    }

    receive() external payable {
        poolBalance += msg.value;
    }
}

