// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

interface IGameController {
    function isAccountFrozen(address) external view returns (bool);
}

/**
 * @title Marketplace
 * @dev Escrow for P2P trades. Create, confirm, dispute, cancel.
 */
contract Marketplace {
    IGameController public gameController;
    address public admin;

    enum EscrowStatus {
        None,
        Pending,
        Delivered,
        Disputed,
        Completed,
        Cancelled
    }

    struct Escrow {
        address seller;
        address buyer;
        uint256 amount;
        EscrowStatus status;
    }

    Escrow[] public escrows;

    event EscrowCreated(uint256 indexed id, address seller, address buyer, uint256 amount);
    event EscrowConfirmed(uint256 indexed id);
    event EscrowDisputed(uint256 indexed id);
    event EscrowResolved(uint256 indexed id, bool toBuyer);
    event EscrowCancelled(uint256 indexed id);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Marketplace: not admin");
        _;
    }

    constructor(address _gameController) {
        admin = msg.sender;
        gameController = IGameController(_gameController);
    }

    function createEscrow(address buyer) external payable {
        require(!gameController.isAccountFrozen(msg.sender), "Marketplace: seller frozen");
        require(!gameController.isAccountFrozen(buyer), "Marketplace: buyer frozen");
        require(msg.value > 0, "Marketplace: zero amount");

        escrows.push(Escrow({
            seller: msg.sender,
            buyer: buyer,
            amount: msg.value,
            status: EscrowStatus.Pending
        }));
        emit EscrowCreated(escrows.length - 1, msg.sender, buyer, msg.value);
    }

    function confirmDelivery(uint256 id) external {
        Escrow storage e = escrows[id];
        require(e.status == EscrowStatus.Pending, "Marketplace: invalid status");
        require(msg.sender == e.buyer, "Marketplace: not buyer");

        e.status = EscrowStatus.Completed;
        (bool ok,) = payable(e.seller).call{value: e.amount}("");
        require(ok, "Marketplace: transfer failed");
        emit EscrowConfirmed(id);
    }

    function disputeEscrow(uint256 id) external {
        Escrow storage e = escrows[id];
        require(e.status == EscrowStatus.Pending, "Marketplace: invalid status");
        require(msg.sender == e.buyer, "Marketplace: not buyer");

        e.status = EscrowStatus.Disputed;
        emit EscrowDisputed(id);
    }

    function cancelEscrow(uint256 id) external {
        Escrow storage e = escrows[id];
        require(e.status == EscrowStatus.Pending, "Marketplace: invalid status");
        require(msg.sender == e.seller, "Marketplace: not seller");

        e.status = EscrowStatus.Cancelled;
        (bool ok,) = payable(e.seller).call{value: e.amount}("");
        require(ok, "Marketplace: refund failed");
        emit EscrowCancelled(id);
    }

    function resolveDispute(uint256 id, bool toBuyer) external onlyAdmin {
        Escrow storage e = escrows[id];
        require(e.status == EscrowStatus.Disputed, "Marketplace: not disputed");

        e.status = EscrowStatus.Completed;
        address recipient = toBuyer ? e.buyer : e.seller;
        (bool ok,) = payable(recipient).call{value: e.amount}("");
        require(ok, "Marketplace: transfer failed");
        emit EscrowResolved(id, toBuyer);
    }

    receive() external payable {}
}

contracts/game/Mixer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

interface IGameController {
    function currentEpoch() external view returns (uint256);
    function isAccountFrozen(address) external view returns (bool);
}

/**
 * @title Mixer
 * @dev Privacy mixer for Chain City. Deposits with withdrawal hash, withdraw after mixDelay epochs.
 * getDeposit returns (amount, depositEpoch, withdrawn) - NOT depositor (per spec).
 */
contract Mixer {
    IGameController public gameController;
    address public admin;
    uint256 public mixDelay = 1;

    struct MixDeposit {
        address depositor;
        uint256 amount;
        uint256 depositEpoch;
        bytes32 withdrawalHash;
        bool withdrawn;
    }

    MixDeposit[] public deposits;

    event MixDepositMade(uint256 indexed index, address indexed depositor, uint256 amount, bytes32 withdrawalHash);
    event MixWithdrawal(uint256 indexed index, address indexed to);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Mixer: not admin");
        _;
    }

    constructor(address _gameController) {
        admin = msg.sender;
        gameController = IGameController(_gameController);
    }

    function setMixDelay(uint256 _delay) external onlyAdmin {
        mixDelay = _delay;
    }

    function mixDeposit(bytes32 withdrawalHash) external payable {
        require(!gameController.isAccountFrozen(msg.sender), "Mixer: account frozen");
        require(msg.value > 0, "Mixer: zero amount");

        uint256 epoch = gameController.currentEpoch();
        deposits.push(MixDeposit({
            depositor: msg.sender,
            amount: msg.value,
            depositEpoch: epoch,
            withdrawalHash: withdrawalHash,
            withdrawn: false
        }));
        emit MixDepositMade(deposits.length - 1, msg.sender, msg.value, withdrawalHash);
    }

    function mixWithdraw(uint256 index, address to, bytes32 secret) external {
        MixDeposit storage d = deposits[index];
        require(!d.withdrawn, "Mixer: already withdrawn");
        require(
            keccak256(abi.encodePacked(secret)) == d.withdrawalHash,
            "Mixer: invalid secret"
        );
        require(
            gameController.currentEpoch() >= d.depositEpoch + mixDelay,
            "Mixer: mixDelay not elapsed"
        );
        require(!gameController.isAccountFrozen(to), "Mixer: recipient frozen");

        d.withdrawn = true;
        (bool ok,) = payable(to).call{value: d.amount}("");
        require(ok, "Mixer: transfer failed");
        emit MixWithdrawal(index, to);
    }

    function getDeposit(uint256 index)
        external
        view
        returns (uint256 amount, uint256 depositEpoch, bool withdrawn)
    {
        MixDeposit storage d = deposits[index];
        return (d.amount, d.depositEpoch, d.withdrawn);
    }

    function getDepositCount() external view returns (uint256) {
        return deposits.length;
    }

    receive() external payable {}
}

