// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

/**
 * @title StudentToken
 * @dev ERC20 with optional drain (rug pull). Creator can drain if _drainable.
 * Simulates liquidity pool via buyTokens/sellTokens.
 */
contract StudentToken is ERC20 {
    address public creator;
    bool private _drainable;

    uint256 public virtualPoolEth;
    uint256 public virtualPoolTokens;

    event TokensBought(address indexed buyer, uint256 ethIn, uint256 tokensOut);
    event TokensSold(address indexed seller, uint256 tokensIn, uint256 ethOut);
    event Drained(address indexed by, uint256 amount);

    constructor(
        string memory name_,
        string memory symbol_,
        uint256 initialSupply,
        bool drainable
    ) ERC20(name_, symbol_) {
        creator = msg.sender;
        _drainable = drainable;
        _mint(address(this), initialSupply);
        virtualPoolTokens = initialSupply;
        virtualPoolEth = 0;
    }

    function drain() external {
        require(msg.sender == creator, "StudentToken: not creator");
        require(_drainable, "StudentToken: not drainable");

        uint256 amount = balanceOf(address(this));
        _transfer(address(this), creator, amount);
        emit Drained(creator, amount);
    }

    function buyTokens() external payable {
        require(msg.value > 0, "StudentToken: zero amount");

        uint256 tokensOut = (msg.value * virtualPoolTokens) / (virtualPoolEth + msg.value);
        require(tokensOut <= balanceOf(address(this)), "StudentToken: insufficient liquidity");

        virtualPoolEth += msg.value;
        virtualPoolTokens -= tokensOut;
        _transfer(address(this), msg.sender, tokensOut);
        emit TokensBought(msg.sender, msg.value, tokensOut);
    }

    function sellTokens(uint256 tokenAmount) external {
        require(tokenAmount > 0, "StudentToken: zero amount");
        require(balanceOf(msg.sender) >= tokenAmount, "StudentToken: insufficient balance");

        uint256 ethOut = (tokenAmount * virtualPoolEth) / (virtualPoolTokens + tokenAmount);

        virtualPoolTokens += tokenAmount;
        virtualPoolEth -= ethOut;
        _transfer(msg.sender, address(this), tokenAmount);
        (bool ok,) = payable(msg.sender).call{value: ethOut}("");
        require(ok, "StudentToken: transfer failed");
        emit TokensSold(msg.sender, tokenAmount, ethOut);
    }

    receive() external payable {
        virtualPoolEth += msg.value;
    }
}

contracts/game/TimelockEscrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

interface IGameController {
    function currentEpoch() external view returns (uint256);
}

/**
 * @title TimelockEscrow
 * @dev Used by ransomware injection. Victim pays ransom, forwards to paymentAddress.
 */
contract TimelockEscrow {
    address public victim;
    address public paymentAddress;
    uint256 public amount;
    uint256 public deadlineEpoch;
    bool public isPaid;
    bool public isExpired;
    IGameController public gameController;

    event RansomPaid(address indexed from, uint256 amount);
    event EscrowExpired();

    constructor(
        address _victim,
        address _paymentAddress,
        uint256 _amount,
        uint256 _deadlineEpoch,
        address _gameController
    ) {
        victim = _victim;
        paymentAddress = _paymentAddress;
        amount = _amount;
        deadlineEpoch = _deadlineEpoch;
        gameController = IGameController(_gameController);
    }

    function pay() external payable {
        require(msg.sender == victim, "TimelockEscrow: not victim");
        require(!isPaid, "TimelockEscrow: already paid");
        require(!isExpired, "TimelockEscrow: expired");
        require(msg.value >= amount, "TimelockEscrow: insufficient amount");

        isPaid = true;
        (bool ok,) = payable(paymentAddress).call{value: amount}("");
        require(ok, "TimelockEscrow: transfer failed");

        if (msg.value > amount) {
            (bool refund,) = payable(victim).call{value: msg.value - amount}("");
            require(refund, "TimelockEscrow: refund failed");
        }
        emit RansomPaid(msg.sender, amount);
    }

    function expire() external {
        require(!isPaid, "TimelockEscrow: already paid");
        require(
            gameController.currentEpoch() > deadlineEpoch,
            "TimelockEscrow: deadline not reached"
        );
        isExpired = true;
        emit EscrowExpired();
    }
}

