// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StudentToken.sol";

interface IGameController {
    function isAccountFrozen(address) external view returns (bool);
}

/**
 * @title TokenFactory
 * @dev Deploys StudentToken instances. Optional drainable flag for rug pull scenario.
 */
contract TokenFactory {
    IGameController public gameController;
    address public admin;

    struct TokenInfo {
        address tokenAddress;
        string name;
        string symbol;
        address creator;
    }

    TokenInfo[] public deployedTokens;
    mapping(address => uint256) public tokenLookup;

    event TokenCreated(address indexed token, string name, string symbol, address creator);

    modifier onlyAdmin() {
        require(msg.sender == admin, "TokenFactory: not admin");
        _;
    }

    constructor(address _gameController) {
        admin = msg.sender;
        gameController = IGameController(_gameController);
    }

    function createToken(
        string calldata name_,
        string calldata symbol_,
        uint256 initialSupply
    ) external returns (address) {
        return _createToken(name_, symbol_, initialSupply, false);
    }

    function createToken(
        string calldata name_,
        string calldata symbol_,
        uint256 initialSupply,
        bool drainable
    ) external returns (address) {
        return _createToken(name_, symbol_, initialSupply, drainable);
    }

    function _createToken(
        string memory name_,
        string memory symbol_,
        uint256 initialSupply,
        bool drainable
    ) internal returns (address) {
        require(!gameController.isAccountFrozen(msg.sender), "TokenFactory: account frozen");

        StudentToken token = new StudentToken(name_, symbol_, initialSupply, drainable);
        address addr = address(token);
        deployedTokens.push(TokenInfo({
            tokenAddress: addr,
            name: name_,
            symbol: symbol_,
            creator: msg.sender
        }));
        tokenLookup[addr] = deployedTokens.length - 1;
        emit TokenCreated(addr, name_, symbol_, msg.sender);
        return addr;
    }

    function getDeployedTokens() external view returns (TokenInfo[] memory) {
        return deployedTokens;
    }
}

